    # this feature exists to give — stops being visible as one line.
    # ⛔ AND THE POSITION IS NEVER WHAT GETS CUT — it is the whole payload; the label is only
    # orientation. Asserted here as `startswith`, because that is the property. There is
    # deliberately NO separate "no room for the position" branch: reaching it needs a `done`/
    # `total` pair of some 76 digits, and a clause no input can reach is one no case can kill.
    # ── THE DIAGNOSTIC WINDOW BELONGS TO THE FAILURE ─────────────────────────────────────
    # ⟳ r2 M1. `run_suite` merges the child's two streams and every CANNOT RUN prints the last
    # 400 characters, so whichever stream goes LAST owns that window. These two cases pin BOTH
    # ends of that trade, because fixing either one alone is how r1 H1 happened: `[FAIL]` is on
    # stdout, a crash-before-output is on stderr, and a guard for one silently permits losing
    # the other.
    with tempfile.TemporaryDirectory() as _wd:
        _wdp = pathlib.Path(_wd)
        # A suite that FAILS while a noisy child floods stderr — r1 H1's harm, from any emitter.
        (_wdp / "flooder.py").write_text(
            'import sys\n'
            'def _self_test():\n'
            '    sys.stderr.write("N" * 600 + "\\n")\n'
            # ⚠ NO `": got "` IN THIS FIXTURE'S OUTPUT, and that is not cosmetic. When the
            # case below fails, its own report line is `[FAIL] <name>: got <got> want <want>`,
            # and `parse_fail_names` truncates at the LAST `": got "` so that a case NAME may
            # contain a colon. A `": got "` inside the VALUE therefore lands after the real
            # one and swallows half the line into the name. MEASURED on the first
            # `--mutate .` of this round: 445 killed, 444 attributed — the one unattributable
            # entry was this case, whose want used to be `'[FAIL] the value is one: got 99'`.
            '    print("  [FAIL] the value is one")\n'
            '    return 1\n'
            'if __name__ == "__main__":\n'
            '    sys.exit(_self_test())\n')
        _nrc, _nso, _nse = run_suite_parts(_wdp, "flooder.py")
        # ⟳ r3: this read `run_suite(...)[1][-400:]`, which STOPPED being the production window
        # when the diagnostic moved to `diagnostic_tail`. A case that outlives the path it was
        # written for keeps passing and guards nothing.
        case("600 B of child stderr cannot push the failure out of the 400-char window",
             (_nrc, "[FAIL] the value is one" in diagnostic_tail(_nso, _nse)), (1, True))
        # (The evidence-object tail is asserted where it is PRODUCED — see the case reading
        #  `ev.files[...]["tail"]`. Recomputing it here is what r3 H2 caught.)
        # ⛔ THE CASE THAT USED TO SIT HERE WAS BLIND TO THE THING IT WAS NAMED FOR — r3 H1. It
        # ran a fixture that raises at import, so stdout was EMPTY and `stderr + stdout` and
        # `stdout + stderr` produced the identical string: green under both orders, and unable
        # to fail for the reason it claimed to guard. It died only when the stderr half was
        # DELETED, which the r1 F7 entry already covers. A premise fixed without the branch
        # being covered — write the case from the CLAUSE.
        # What replaces it drives the real hazard: a suite that crashes AFTER printing, which is
        # 28 of the 38 real suites (their GREEN stdout already exceeds the window;
        # `check-paid-caller-arrival.py` is 16,701 B).
        (_wdp / "late.py").write_text(
            'import sys\n'
            'def _self_test():\n'
            '    print("S" * 800)\n'
            '    raise RuntimeError("the tree went bad underneath")\n'
            'if __name__ == "__main__":\n'
            '    sys.exit(_self_test())\n')
        _lrc, _lso, _lse = run_suite_parts(_wdp, "late.py")
        _ltail = diagnostic_tail(_lso, _lse)
        case("a suite that crashes AFTER 800 B of stdout still shows its traceback",
             (_lrc, "the tree went bad underneath" in _ltail), (1, True))

    # ── THE WINDOW, AS A PURE FUNCTION ───────────────────────────────────────────────────
    # ⛔ NEITHER STREAM MAY EVICT THE OTHER. Two rounds were spent choosing a concatenation
    # order; both orders lose, because the order was never the question. These assert the
    # PROPERTY — both halves reach the reader — rather than any particular arrangement.
    case("a flooded stderr cannot evict stdout's failure from the window",
         "[FAIL] the one that matters" in diagnostic_tail("[FAIL] the one that matters",
                                                          "E" * 5000), True)
    case("...and a flooded stdout cannot evict stderr's traceback",
         "RuntimeError: boom" in diagnostic_tail("S" * 5000, "RuntimeError: boom"), True)
    # ⛔ THE SPLIT POINT ITSELF — r4 B1, the NINTH instance, and in the code that fixed the eighth.
    # The whole content of the fix is "each stream is guaranteed half the window", and nothing
    # asserted the half. MEASURED over a green control, mutating only `half = window // 2`: every
    # value in the open band 20 < half < 399 kept the suite at 121/121. At `half = 50` — green —
    # a REAL control crash (`check-paid-caller-arrival.py`, 16,701 B of stdout) showed 50
    # characters of stack frames and NEITHER the exception type NOR its message; at `half = 350`,
    # also green, stdout was cut to 50 characters, shorter than most `[FAIL] <name>` lines here.
    # ⭐ WHY THE EXISTING CASE COULD NOT SEE IT, and it is r3 B1's diagnosis exactly: the late.py
    # fixture's exception line is 41 characters and a real one is 84, so the case proved `half ≳ 41`
    # for a corpus that needs `half ≳ 84`. The input was an order of magnitude inside the boundary,
    # on the safe side. r3 put its cases AT the boundary for `progress_line` — where the fix was —
    # and nowhere near it for the function that fix introduced.
    # The want is a LITERAL 200. `window // 2` on the right-hand side would move with the subject,
    # which is r2's defect, and this file has now paid for each of those separately.
    # ⟳ r5 L2: the want was `len(...) == 200` — a LENGTH, when the property is about a SIDE. Both
    # streams were `"S"`/`"E"` of equal size, so emitting them in the wrong order passed too.
    # Asserting the content costs nothing and pins both at once.
    case("both streams flooded, and the stderr half is exactly half the window",
         diagnostic_tail("S" * 5000, "E" * 5000).split("\n")[0], "E" * 200)
    # ⛔ AND IT IS THE END OF EACH STREAM THAT IS KEPT, NEVER THE START — r5 B1, found by BOTH
    # review halves, and the ninth consecutive round in which the guard was written and the
    # fixture could not see it. MEASURED: `out[-out_keep:]` → `out[:out_keep]` left the suite at
    # 124/124, and against the real CANNOT RUN path a control emitting 700 B of stdout ending in
    # `[FAIL] final case` reported none of it.
    # ⭐ THE REASON NO CASE COULD SEE IT, and this is the sharpest lesson of the five rounds:
    # every fixture above is `"S" * 5000` — a string at the boundary of MAGNITUDE with no
    # POSITION, so its first 200 characters and its last 200 are byte-identical. It can pin a
    # length and can NEVER pin a direction. r4 asked "is the input at the edge?"; the question
    # that catches this is **"what two inputs would this case have to tell apart, and can it?"**
    # A FIXTURE MUST DIFFER FROM ITSELF ALONG THE AXIS THE PROPERTY IS ABOUT.
    _dt_ends = diagnostic_tail("FIRST" + "S" * 5000 + "LAST", "OPEN" + "E" * 5000 + "SHUT")
    case("...and it is the END of each stream that is kept, never the start",
         (_dt_ends.endswith("LAST"), _dt_ends.split("\n")[0].endswith("SHUT"),
          "FIRST" in _dt_ends, "OPEN" in _dt_ends), (True, True, False, False))
    # ⟳ r5 H1 — THE MIRROR OF THE GIVE-BACK, which existed in one direction only. The floor's
    # spare-budget term reads `len(out)`, and swapping it for `len(err)` was green: a suite that
    # raises at import (no stdout, traceback on stderr — the shape this file uses as a fixture)
    # would get 200 characters of traceback instead of 400, discarding half the budget for the
    # failure shape where the traceback is the ONLY evidence there is.
    case("...and a quiet stdout gives its whole half back to stderr",
         len(diagnostic_tail("", "E" * 5000)), 400)
    # ⚠ THE BUDGET IS A CEILING, so it is asserted as a LITERAL — r3's Blocking was a want that
    # moved with its subject, and `DIAGNOSTIC_WINDOW` on both sides would be exactly that again.
    # ⟳ r4 M1: this was `<= 401`, and an inequality with slack asserts a HALF-SPACE, not a value —
    # the separator lived in that one character of slack, so joining the halves with `""` (fusing
    # the last stderr line and the first stdout line into one sentence, in the report a reader
    # consults precisely when they cannot trust anything) gave 400 and passed.
    case("...and the window never exceeds its budget, however much is offered",
         len(diagnostic_tail("S" * 5000, "E" * 5000)), 401)
    # ⟳ r4 M2 — `.strip()` was a behaviour this commit chose with no case that could fail for it.
    # Unstripped, a stderr of just "\n" is charged against the budget AND survives the `if p`
    # filter, so the report opens with a blank line.
    case("...and a whitespace-only stream is dropped rather than charged to the budget",
         diagnostic_tail("done\n", "  \n"), "done")
    # ...while a silent stderr costs the reader nothing: the unused half goes to stdout, so the
    # common case keeps the full 400 characters it had before any of this.
    case("...and a quiet stderr gives its whole half back to stdout",
         len(diagnostic_tail("S" * 5000, "")), 400)

    # ⛔ THE WANT IS THE LITERAL 79, NOT `PROGRESS_WIDTH` — r2 B1, and the SEVENTH instance of this
    # class on this line of work, introduced by the fix to the sixth. Written as
    # `want=(PROGRESS_WIDTH, …)` the expected value is DERIVED FROM THE SUBJECT: both sides move
    # together, so the case says "the line is as wide as the constant says", which is true of every
    # constant that truncates at all. MEASURED: at 80, 90, 100, 120 and 200 the suite stayed
    # 111/111 — a guard with a floor and no ceiling, when the ceiling is the entire point. A
    # literal cannot move with the subject, and the manifest entry that widens the constant dies
    # here.
    _pl_long = progress_line(164, 434, "x" * 300)
    case("a label too long for one row is truncated, and says so",
         (len(_pl_long), _pl_long[-1], _pl_long.startswith("[164/434] ")),
         (79, "…", True))
    # ⛔ AND THE THRESHOLD ITSELF, WHICH THE TWO CASES AROUND IT DO NOT REACH — r3 B1, the EIGHTH
    # instance, inside the fix to the seventh. Pinning the constant to a literal gave it a ceiling;
    # the COMPARISON on `len(label) <= room` kept none, because the inputs are 4, 13, 40 and 300
    # characters and the boundary is at 69/70. MEASURED as survivors over a green control:
    #     `<= room + 1`   -> 114/114 passed      (6 real labels then emit an 80-column line)
    #     `<= room + 20`  -> 114/114 passed      (82 of 445 real labels wrap, up to 99 columns)
    #     `<  room`       -> 114/114 passed
    # ⭐ THE LESSON THAT DID NOT TRANSFER: r2 asked whether the WANT moves with the subject, and
    # fixed that. The INPUT matters just as much — `"x" * 300` is true of every threshold from 1
    # to 299, so it pins the far side and says nothing about where the edge is. Test AT the edge.
    # `room` is 79 - len("[164/434] ") = 69. Both wants are literals for the reason above.
    case("a label of exactly the remaining width is NOT truncated",
         progress_line(164, 434, "z" * 69), "[164/434] " + "z" * 69)
    case("...and one character more IS, back to exactly one row",
         (len(progress_line(164, 434, "z" * 70)), progress_line(164, 434, "z" * 70)[-1]),
         (79, "…"))
    # ⛔ AND THE HEAD IS A VARIABLE, WHICH NO CASE HAD EVER TREATED AS ONE — r6 B1. Every case
    # above passes `(164, 434)`, whose head `"[164/434] "` is exactly TEN characters, so
    # `PROGRESS_WIDTH - len(head)` and `PROGRESS_WIDTH - 10` are INDISTINGUISHABLE and the second
    # survives at 126/126. ⭐ r5 asked "what two inputs must this case tell apart?" of the LABEL
    # and varied its magnitude and position; nobody asked it of the OTHER OPERAND, which is a
    # fixture constant in every case. THE UNTESTED AXIS WAS NOT A PROPERTY OF THE INPUT — IT WAS
    # A PARAMETER NOBODY VARIED.
    # The harm is live: `run_mutations` reports `len(muts)` = 466, so production heads are 8, 9
    # and 10 characters wide (true `room` 71, 70, 69). Frozen at 69, sixteen real manifest names
    # get an ellipsis they did not earn — the exact harm another entry exists for. And past 1000
    # mutations the head is 11, `room` is 68, and a 69-character label yields 80 columns: the
    # bound this function exists to hold, broken.
    # The falsifier is a PAIR at two head widths, with literal wants that cannot both hold for a
    # frozen `room`.
    case("a narrower head leaves more room, and a 73-char label fits exactly",
         progress_line(1, 9, "w" * 73), "[1/9] " + "w" * 73)
    case("...and a wider head leaves less, so a shorter label is truncated",
         progress_line(4321, 9876, "w" * 68), "[4321/9876] " + "w" * 66 + "…")
    case("...and a label that already fits is left exactly alone",
         progress_line(164, 434, "y" * 40), "[164/434] " + "y" * 40)
    # ⚠ run_mutations must stay SILENT unless a caller asks. Its own suite drives it dozens of
    # times, and the OUTER harness captures a suite's stderr into `control_is_green` — progress
    # leaking from a nested run would be read as part of that suite's output.
    with tempfile.TemporaryDirectory() as _dp:
        _dpp = pathlib.Path(_dp)
        (_dpp / "p.py").write_text(
            'def f():\n    return 1\n\n\n'
            'def _self_test():\n'
            '    if f() != 1:\n'
            '        print("  [FAIL] the value is one")\n'
            '        return 1\n'
            '    print("1/1 passed")\n'
            '    return 0\n\n\n'
            'import sys\n'
            'if __name__ == "__main__":\n'
            '    sys.exit(_self_test())\n')
        _pm = [{"name": f"m{i}", "file": "p.py",
                "edits": [["def f():\n    return 1", f"def f():\n    return {i + 1}"]],
                "expect": ["the value is one"]} for i in (1, 2)]
        _seen: list = []
        run_mutations(_dpp, _pm, {"p.py"}, progress=lambda *a: _seen.append(a))
        case("the caller is told once per mutation, with the running position",
             _seen, [(1, 2, "m1"), (2, 2, "m2")])
        # ⛔ CAPTURE THE STREAM, NEVER AN UNWIRED LIST. This case was
        # `_quiet: list = []` / `run_mutations(...)` / `case(..., _quiet, [])` — and nothing in
        # the program could append to `_quiet`, so it asserted `[] == []`. r1 B1, and the SIXTH
        # instance on this branch of a guard whose existence is cased and whose content is not.
        # MEASURED at the time: adding an `else: stderr_progress(...)` to `run_mutations` — the
        # exact defect the case names — left the suite at `105/105 passed` while its own stderr
        # grew 542 B → 766 B. ⭐ THE TELL GENERALISES: the commit that added it added FOUR cases
        # and THREE manifest entries. A case for which no mutation can be written is usually one
        # no production edit can reach. COUNT CASES AGAINST ENTRIES.
        _qe = io.StringIO()
        with contextlib.redirect_stderr(_qe):
            run_mutations(_dpp, _pm, {"p.py"})
        case("...and says NOTHING when no caller asked", _qe.getvalue(), "")

    # ⛔ THE STREAM IS THE POINT. The verdict is stdout and is parsed; progress on stdout would
    # put "[31/38] …" where a reader — and `tally_line`'s own cases — expect the tally.
    _po, _pe = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(_po), contextlib.redirect_stderr(_pe):
        stderr_progress(3, 9, "x.py")
    case("progress goes to stderr, never to the stream carrying the verdict",
         (_po.getvalue(), _pe.getvalue().strip()), ("", "[3/9] x.py"))
    # ⛔ THE FLUSH CLAUSE, CASED — r1 L1, and both halves found it uncovered while disagreeing
    # about why. It cannot be cased against a StringIO (`getvalue()` sees writes regardless), so
    # the case constructs the environment where flush DECIDES: a real file stream, block-buffered
    # at 8 KiB, READ BEFORE IT IS CLOSED. Without `flush=True` this reads `''`. MEASURED, both
    # directions. The docstring above used to assert a mechanism (pipes) that does not exist;
    # this asserts the one that does.
    with tempfile.TemporaryDirectory() as _fd:
        _fp = pathlib.Path(_fd) / "e.txt"
        _fh = open(_fp, "w")
        try:
            with contextlib.redirect_stderr(_fh):
                # ⚠ DIFFERENT ARGUMENTS FROM THE CASE ABOVE, deliberately — r6, via
                # `check-fixture-variation.py`. Both sites used to pass `(3, 9, "x.py")`, so
                # `stderr_progress`'s three parameters were indistinguishable from constants and
                # nothing could catch it forwarding the wrong one to `progress_line`.
                stderr_progress(7, 38, "check-docs.py")
            case("a progress line reaches a block-buffered stream before the process exits",
                 _fp.read_text(), "[7/38] check-docs.py\n")
        finally:
            _fh.close()

    # ── THE SUMMARY STATES THE AFFIRMATIVE NUMBERS ───────────────────────────────────────
    # ⛔ THE SHAPE THIS EXISTS FOR, measured on this branch: eight entries, every one killed,
    # NOT ONE attributable — and the old line said `8 mutation(s), 0 survivor(s)`, which is
    # exactly what a perfect run says. The reader had to scroll a 400-entry log to find out.
    _mk = lambda muts, surv: Measured(
        files={"a.py": True}, declared=len(muts), mutations=muts, survivors=surv,
        controls_green=True)
    _all_ok = [{"name": "x", "measured": True, "attributed": True, "caught": True},
               {"name": "y", "measured": True, "attributed": True, "caught": True}]
    case("the tally states how many were killed AND how many were attributed",
         tally_line(True, _mk(_all_ok, [])),
         "OK — delivered scripts mutated: 1 file(s), 2 mutation(s), 2 killed, "
         "2 attributed to the case each names, 0 survivor(s) — measured over "
         "the WHOLE manifest")
    # ⭐ killed-but-unattributable no longer reads as success.
    _none_named = [dict(m, attributed=False) for m in _all_ok]
    case("⭐ a run where everything died and nothing was attributed says so in the FIRST line",
         "2 killed, 0 attributed" in tally_line(False, _mk(_none_named, [])), True)
    case("...and that is visibly different from a clean run",
         tally_line(False, _mk(_none_named, [])) != tally_line(True, _mk(_all_ok, [])), True)
    case("a survivor is not counted as a kill",
         "1 killed" in tally_line(False, _mk(_all_ok, ["y"])), True)

    # ── --shard: THE PARTITION IS THE WHOLE CONTRACT (backlog #217) ──────────────────────
    # ⭐ THE LOAD-BEARING FALSIFIER. Splitting the sweep across N parallel jobs is worth
    # nothing unless every mutation lands in exactly one shard: a partition that DROPS an
    # entry makes N green jobs report success over work nobody did, which is strictly worse
    # than the slow sweep it replaces, and a partition that DUPLICATES one silently pays the
    # cost twice. Asserted over several N, including an N larger than the list.
    #
    # ⚠ A MULTISET EQUALITY, NOT A LENGTH AND NOT A SET. `sorted(flat) == sorted(items)`
    # with distinct items is pairwise disjointness AND union equality in one observation;
    # a length alone passes when one entry is dropped and another duplicated, and a SET
    # comparison cannot see the duplicate at all.
    _items = [f"m{i}" for i in range(37)]
    _parts = {n: [shard_slice(_items, i, n) for i in range(1, n + 1)] for n in (1, 2, 3, 7, 40)}
    case("⭐ every mutation runs in EXACTLY ONE shard and the union is the whole manifest",
         {n: sorted(x for p in ps for x in p) == sorted(_items) for n, ps in _parts.items()},
         {1: True, 2: True, 3: True, 7: True, 40: True})
    case("...and the shards of one N are PAIRWISE DISJOINT, counted not assumed",
         {n: sum(len(p) for p in ps) for n, ps in _parts.items()},
         {1: 37, 2: 37, 3: 37, 7: 37, 40: 37})
    # ⛔ ROUND-ROBIN, NOT CONTIGUOUS — THE CRUX, and the only case that can tell them apart.
    # `muts` is built in sorted-by-file order, so ONE FILE'S ENTRIES ARE CONTIGUOUS. Measured
    # on PR #360's branch: one guard held 183 of the manifest's entries against its own ~30s
    # suite — ~87 of the ~90 minutes. A contiguous split hands that whole block to one shard
    # and that shard still exceeds the ceiling, while the others idle; sharding BY FILE is
    # worse still, since a single file can exceed the ceiling alone. Both pass the partition
    # case above, which is why BALANCE needs its own.
    _cost = ["big"] * 10 + ["small"] * 2
    case("⛔ round-robin spreads ONE file's contiguous block evenly; a contiguous split cannot",
         [sum(1 for x in shard_slice(_cost, i, 4) if x == "big") for i in range(1, 5)],
         [3, 3, 2, 2])
    case("a shard past the end of the list is empty rather than an error",
         (shard_slice(_cost, 1, 1), shard_slice([], 1, 2)), (_cost, []))

    # ── ...AND THE REFUSALS. An empty shard that "passes" measured nothing ───────────────
    # ⚠ EACH REFUSAL IS ASSERTED BY ITS SENTENCE, not by "something was refused". The two arms
    # both return `(None, <a CANNOT RUN>)`, so a case that only checks for None cannot tell them
    # apart — and with the numbers parsed up front (see `parse_shard`) severing one arm leaves
    # the other answering for it. The sentence is the only observation that separates them.
    case("--shard 2/5 parses", parse_shard("2/5"), ((2, 5), None))
    case("...a non-integer shard is a SENTENCE and a CANNOT RUN, never a traceback",
         (parse_shard("x/5")[0], (parse_shard("x/5")[1] or "").startswith("CANNOT RUN"),
          "not of the form I/N" in (parse_shard("x/5")[1] or "")), (None, True, True))
    case("...so is a shard with no N at all",
         (parse_shard("3")[0], "not of the form I/N" in (parse_shard("3")[1] or "")),
         (None, True))
    case("...shard 0 does not exist, and the refusal says which shard was asked for",
         (parse_shard("0/4")[0], "--shard 0/4 names a shard that does not exist"
          in (parse_shard("0/4")[1] or "")), (None, True))
    case("...nor shard 5 of 4", parse_shard("5/4")[0], None)
    case("...nor any shard of zero shards", parse_shard("1/0")[0], None)

    # ── ROUND 6 L1/L2/L3 — "A DECIMAL INTEGER" MUST MEAN ONE THING, AND IT MEANT THREE.
    # `\d` and `str.isdigit()` are UNICODE-WIDE: `1/٨` parsed as `(1, 8)` from an Arabic-Indic
    # eight, `٠` became shard 1 of 8 through a guard written to stop exactly that, and 128 further
    # code points (`²`, `፩`) pass the class while `int()` RAISES — a traceback this function's own
    # docstring forbids. The pattern is an explicit byte class now, so every string it matches is
    # one `int()` accepts, and the traceback case cannot arise.
    case("a UNICODE digit is not a decimal integer — round 6 L2",
         (parse_shard("1/٨")[0], parse_shard("٠/8")[0], parse_shard("１/8")[0]), (None, None, None))
    case("...and a code point that is `isdigit` but not `int`-able REFUSES, never raises — L3",
         (parse_shard("²/8")[0], "not of the form I/N" in (parse_shard("²/8")[1] or "")),
         (None, True))
    case("...and a LEADING ZERO is refused, so CANONICAL in the message is a claim the pattern keeps",
         (parse_shard("00/8")[0], parse_shard("08/8")[0], parse_shard("01/8")[0]),
         (None, None, None))
    case("...and so is whitespace, including a TRAILING NEWLINE — round 6 codex Low. `$` matches "
         "before a final newline and `.strip()` swallowed the rest, so the canonical claim was "
         "false at its own boundary; the CI seam interpolates a shell value, where a stray "
         "newline is the likeliest contaminant",
         (parse_shard(" 1/8")[0], parse_shard("1/8 ")[0], parse_shard("1/8\n")[0],
          parse_shard("1/8\t")[0]), (None, None, None, None))

    # ── ROUND 6 M1 — the 0->1 conversion lives HERE, where a suite can see it. Three versions of
    # this rule shipped inside a workflow `run:` block, which has no self-test, no mutation entry
    # and no ratchet coverage, and each was wrong in a different way.
    case("--shard0 is ZERO-based: index 0 is shard 1", parse_shard("0/8", zero_based=True)[0], (1, 8))
    case("...and index N-1 is shard N", parse_shard("7/8", zero_based=True)[0], (8, 8))
    case("...and index N is refused, because it is one past the last shard",
         (parse_shard("8/8", zero_based=True, flag="--shard0")[0],
          "--shard0 8/8 names a shard that does not exist"
          in (parse_shard("8/8", zero_based=True, flag="--shard0")[1] or "")),
         (None, True))
    case("...and the refusal names the FLAG the caller actually used",
         ("--shard0" in (parse_shard("x/5", flag="--shard0")[1] or ""),
          "--shard" in (parse_shard("x/5")[1] or "")), (True, True))
    case("⛔ an EMPTY shard is refused, and the refusal names the count that empties it",
         ((shard_refusal(4, 4, 3) or "").startswith("CANNOT RUN"),
          "3 mutation(s)" in (shard_refusal(4, 4, 3) or "")), (True, True))
    case("...and a shard with work in it is not refused", shard_refusal(2, 3, 9), None)

    # ── THE VERDICT LINE NAMES WHICH SLICE IT MEASURED ──────────────────────────────────
    # ⛔ "The final line of STDOUT names the mode" (see the docstring) is now too weak: a
    # sharded run's line is a verdict about a FRACTION of the manifest, and read without the
    # shard it is indistinguishable from a whole-repo pass in a CI log.
    # ⛔ ROUND 1, CODEX MEDIUM — THE MODE REFUSAL, WHICH `--self-test` USED TO OUTRUN. These
    # case `shard_mode_refusal` rather than `main`, because `main(["--self-test", …])` would
    # re-enter the suite running this case. ⚠ The FIRST row is the one the defect needed: a
    # shard alongside --self-test, which exited 0 and printed a clean result. The coordinator
    # had cased the SECOND row only — `--shard` with no mode at all — which refused correctly
    # the whole time.
    case("⛔ a shard alongside --self-test is refused, not silently accepted — the mode runs no "
         "mutations, so a shard over it would report success for a subject nothing touched",
         ((shard_mode_refusal("2/8", None) or "").startswith("CANNOT RUN"),
          (shard_mode_refusal("garbage", None) or "").startswith("CANNOT RUN"),
          "NOTHING WAS MEASURED" in (shard_mode_refusal("0/0", None) or "")),
         (True, True, True))
    case("...and a shard WITH --mutate is the one combination that means something",
         shard_mode_refusal("2/8", "."), None)
    case("...and no shard at all is never refused, whatever the mode",
         (shard_mode_refusal(None, None), shard_mode_refusal(None, ".")), (None, None))
    # ⛔ ROUND 1 H1 + ROUND 2 H1 — AND THE SECOND EXISTS BECAUSE THE FIRST CASE ASSERTED THE
    # MECHANISM. A mutant compiled to `__pycache__` outlives the restore of its own source:
    # Python validates a cache on the source's (mtime, size), and a restore inside one mtime
    # tick still looks current, so the next importer gets the MUTANT. `check-banner-armed.py`
    # imports `observer_log`, which is how five of its cases failed in an AFTER-control.
    #
    # ⛔ THE RACE HAS TWO HALVES AND THE FIRST FIX CLOSED ONE. `PYTHONDONTWRITEBYTECODE` stops
    # this run WRITING a cache; it says nothing about READING one that arrived already made.
    # `stage_tree` used `copytree` with no `ignore=`, and `copy2` preserves mtime and size — the
    # exact pair Python checks — so the repository's own 89-file `scripts/__pycache__/` was
    # copied in looking current. Round 2 reproduced the original symptom on the tree that had
    # "fixed" it, down to the same five case names.
    #
    # ⭐ THE FIRST CASE HERE ASSERTED TWO DICT LOOKUPS UNDER A SENTENCE CLAIMING A PROPERTY, so
    # it passed over a tree where the property was false. These assert the PROPERTY: stage a
    # tree that HAS a cache, and demand the staged copy has none.
    with tempfile.TemporaryDirectory() as _cd, tempfile.TemporaryDirectory() as _cd2:
        _fake = pathlib.Path(_cd)
        for _rel in HARNESS_TREE:
            (_fake / _rel).mkdir(parents=True, exist_ok=True)
        (_fake / "scripts" / "__pycache__").mkdir(parents=True, exist_ok=True)
        (_fake / "scripts" / "__pycache__" / "poisoned.cpython-314.pyc").write_bytes(b"\x00mutant")
        (_fake / "scripts" / "keep.py").write_text("x = 1\n")
        _out = pathlib.Path(_cd2) / "staged"
        _problems = stage_tree(_fake, _out)
        case("⛔ no bytecode cache reaches a staged tree — the source is copied, the compiled "
             "artefact is not, or a mutant .pyc arrives looking current and the next importer "
             "silently gets it",
             (_problems,
              [str(f.relative_to(_out)) for f in _out.rglob("*.pyc")],
              (_out / "scripts" / "keep.py").read_text()),
             ([], [], "x = 1\n"))
    with tempfile.TemporaryDirectory() as _bd, tempfile.TemporaryDirectory() as _bd2:
        # ⚠ TWO DISTINCT DIRECTORIES. `child_env` derives its paths FROM its argument, so a
        # suite handing it one value cannot tell it from a constant — `check-fixture-variation`
        # refused this case's first draft for exactly that.
        _e1, _e2 = child_env(pathlib.Path(_bd)), child_env(pathlib.Path(_bd2))
        case("...and the other half of the race: no suite the harness spawns may WRITE a cache "
             "either, or this run poisons the next one",
             (_e1.get("PYTHONDONTWRITEBYTECODE"), _e2.get("PYTHONDONTWRITEBYTECODE")),
             ("1", "1"))
        # Backlog #407: `child_env` is BORROWED (`check-selftest-counts.audit` runs every suite under it to count its
        # cases), so the mutation-run marker must not ride on it — measured, it did, and the count check saw 100 of 102.
        case("...but `child_env` alone does NOT mark a mutation run — it is borrowed outside one (backlog #407)",
             (_e1.get(MUTATION_RUN_ENV), _e2.get(MUTATION_RUN_ENV)), (None, None))
        # r1 (Codex P1, Claude L3): this suite itself runs under the marker when the harness re-runs it as a control, so
        # an INHERITED marker must be stripped too — measured, without it this suite was 247/248 under the marker.
        _ambient = os.environ.get(MUTATION_RUN_ENV)
        os.environ[MUTATION_RUN_ENV] = "1"
        try:
            _inherited = child_env(pathlib.Path(_bd)).get(MUTATION_RUN_ENV)
        finally:
            if _ambient is None:
                os.environ.pop(MUTATION_RUN_ENV, None)
            else:
                os.environ[MUTATION_RUN_ENV] = _ambient
        case("⭐ ...and STRIPS a marker it inherits, so a borrower run inside a mutation run counts in full (backlog #407)",
             (_inherited, os.environ.get(MUTATION_RUN_ENV)), (None, _ambient))
        _probe = pathlib.Path(_bd) / "marker_probe.py"
        _probe.write_text("import os\nprint(os.environ.get('PLAN_CODE_MUTATION_RUN'))\n")
        case("⭐ ...and every suite the harness itself spawns IS told it is a mutation run (backlog #407)",
             run_suite_parts(pathlib.Path(_bd), "marker_probe.py")[:2], (0, "1\n"))
        case("...and the redirected home is derived from the directory it is given, so the two "
             "trees cannot share one home", _e1["HOME"] == _e2["HOME"], False)

    case("the slice is named when there is no shard", shard_label(None), "the WHOLE manifest")
    case("the --only slice says it is a DIAGNOSTIC, not the gate",
         "DIAGNOSTIC" in shard_label(None, frozenset({"scripts/a.py"})), True)
    case("sweep_estimate: each target's control x (its mutations + the re-control)",
         sweep_estimate({"a": 2.0, "b": 10.0}, [{"file": "a"}, {"file": "a"}, {"file": "b"}]), 26.0)
    case("...over another world", sweep_estimate({"x": 1.5}, [{"file": "x"}]), 3.0)
    # ⭐ 2026-10-25's real run: 183 x ~40s beside 30 x ~0.3s — about two hours.
    _big = [{"file": "scripts/check-main-drivable.py"}] * 183 + [{"file": "scripts/check-merge-ready.py"}] * 30
    _secs = {"scripts/check-main-drivable.py": 40.0, "scripts/check-merge-ready.py": 0.3}
    _why = local_budget_refusal(_secs, _big, 600) or ""
    case("⭐ the 2026-10-25 run is refused, naming the costly file and the one-run flag",
         (_why.startswith(LOCAL_REFUSAL), "check-main-drivable.py: 183 mutation(s)" in _why,
          "--allow-long-local" in _why), (True, True, True))
    case("...while its partial run alone is not", local_budget_refusal(_secs, _big[183:], 600), None)
    case("...a run exactly AT the budget is not refused", local_budget_refusal({"y": 5.0}, [{"file": "y"}], 10.0), None)
    case("...and no budget (CI, or --allow-long-local) never refuses", local_budget_refusal(_secs, _big, None), None)
    # ⚠ The SENTENCE is asserted, not only rc 2: a bare `main([])` is rc 2 too, so a case on the
    # exit code alone would pass with the refusal deleted.
    for _argv, _says in ((["--only", "scripts/a.py"], "only mean something with --mutate"),
                         (["--allow-long-local"], "only mean something with --mutate"),
                         (["--mutate", ".", "--only", "scripts/a.py", "--shard", "1/2"], "two different slices"),
                         (["--seeds", "3,5"], "--seeds only means something with --mutate"),
                         # a NONEXISTENT root, not `.`: with the refusal mutated away, `.` would start a
                         # real whole-manifest sweep inside this suite; this root ends at "not a directory".
                         (["--mutate", "/nonexistent-root", "--seeds", "3,3"], "repeat")):
        _se = io.StringIO()
        with contextlib.redirect_stderr(_se), contextlib.redirect_stdout(io.StringIO()):
            _rc_arg = main(_argv)
        case(f"{' '.join(_argv[:2])}{' ... --shard' if '--shard' in _argv else ''} is refused, rc=2, saying why",
             (_rc_arg, _says in _se.getvalue()), (2, True))
    case("...and it is named I of N, in that order, when there is one",
         shard_label((2, 5)), "shard 2 of 5 (round-robin)")
    # ⚠ THE WIRING, NOT ONLY THE FUNCTION — this file's own recorded lesson (round 6, M5):
    # extracting a helper buys coverage of the helper and the CALL inherits the blind spot.
    _ndv = Measured(files={}, declared=2, mutations=[
        {"name": "a", "caught": False, "measured": True, "nondeterministic": "x", "seeds": [3, 7]},
        {"name": "b", "caught": True, "attributed": True, "measured": True, "seeds": [3, 7]}],
        survivors=["a"], controls_green=True)
    case("⭐ #506: the tally COUNTS a nondeterministic mutant separately and is never 'killed' for it",
         ("1 killed" in tally_line(False, _ndv), "1 NONDETERMINISTIC" in tally_line(False, _ndv),
          tally_line(False, _ndv).endswith("under PYTHONHASHSEED 3, 7")), (True, True, True))
    case("...and a run with no nondeterministic mutant does not mention it",
         "NONDETERMINISTIC" in tally_line(True, _mk(_all_ok, [])), False)
    _flv = Measured(files={}, declared=2, mutations=[
        {"name": "a-flaky", "caught": False, "attributed": False, "measured": True, "flaky": True},
        {"name": "b", "caught": True, "attributed": True, "measured": True}],
        survivors=["a-flaky"], controls_green=True)
    case("⭐ #495: the tally NAMES a FLAKY mutant on an OK run, and never counts it as killed",
         ("OK — " in tally_line(True, _flv), "1 killed" in tally_line(True, _flv),
          "1 FLAKY (among the survivors, NOT red: a-flaky)" in tally_line(True, _flv)), (True, True, True))
    case("...and a run with no flaky mutant does not mention it",
         "FLAKY" in tally_line(True, _mk(_all_ok, [])), False)
    case("the tally line names an --only slice as a DIAGNOSTIC",
         tally_line(True, _mk(_all_ok, []), None, frozenset({"scripts/x.py"})).endswith(
             "measured over ONLY scripts/x.py — a DIAGNOSTIC slice, not the gate"), True)
    case("...and so does the NOT-MEASURED line for one",
         not_measured_line(NotMeasured.from_counts([], 2, {}), None, frozenset({"scripts/y.py", "scripts/z.py"})).endswith(
             "measured over ONLY scripts/y.py, scripts/z.py — a DIAGNOSTIC slice, not the gate"), True)
    case("the tally line says which slice it is about",
         tally_line(True, _mk(_all_ok, []), (1, 3)).endswith(
             "0 survivor(s) — measured over shard 1 of 3 (round-robin)"), True)
    case("...and so does the NOT-MEASURED line",
         not_measured_line(NotMeasured.from_counts([], 2, {}), (3, 4)).endswith(
             " — measured over shard 3 of 4 (round-robin)"), True)
    # ⚠ A SECOND CALL SITE, WITH A DIFFERENT VERDICT AND AN EXPLICIT `None` — required by
    # `check-fixture-variation.py`, and the reason is this file's own round-6 finding: at one
    # call site a parameter is indistinguishable from a constant, so no case can tell a clause
    # that READS it from one that ignores it. The shard is spelled out rather than defaulted,
    # because an omitted argument is not a second value.
    case("...and the NOT-MEASURED line says WHOLE manifest when no shard was asked for",
         not_measured_line(
             NotMeasured.from_counts([{"name": "x", "measured": True}], 3, {"a.py": True}),
             None).endswith(" — measured over the WHOLE manifest"), True)

    # ── THE ENTRY POINT'S REFUSALS. rc 2 = CANNOT RUN, and it must not read as rc 1 ──────
    # ⚠ rc AND A SUBSTRING. `main` returns 2 from four different places, so an rc-only
    # assertion cannot tell this refusal from the bare-invocation one next to it.
    _se = io.StringIO()
    with contextlib.redirect_stderr(_se):
        _rc_ns = main(["--shard", "2/5"])
    case("--shard without --mutate is CANNOT RUN, not a silent whole-manifest run",
         (_rc_ns, "--shard" in _se.getvalue() and "CANNOT RUN" in _se.getvalue()), (2, True))
    # ⛔ AND THE SAME, ASKED OF EVERY FLAG IN `SHARD_FLAGS` — ROUND 7 H1. `--shard0` existed for
    # a whole round while `main` asked the mode question of `a.shard` ALONE, so
    # `--self-test --shard0 garbage` printed a clean `169/169 passed` and exited 0. ⚠ The
    # assertion is driven BY THE DICT, so a third flag is covered the moment it is declared
    # rather than when somebody remembers to add a case — which is the failure this replaces.
    _flag_refusals = {}
    for _f in SHARD_FLAGS:
        _sef = io.StringIO()
        with contextlib.redirect_stderr(_sef):
            _flag_refusals[_f] = (main([f"--{_f}", "2/5"]), _sef.getvalue())
    case("EVERY shard flag without --mutate is CANNOT RUN, and the refusal names that flag",
         {_f: (_rc, f"--{_f}" in _out and "CANNOT RUN" in _out)
          for _f, (_rc, _out) in _flag_refusals.items()},
         {_f: (2, True) for _f in SHARD_FLAGS})
    case("...and there is more than one of them, so the loop above is not a one-element dressing",
         len(SHARD_FLAGS) > 1, True)
    # ⛔ THE EMPTY STRING, FOR EVERY FLAG — round 7 H1's other half. `""` is FALSY, so a truthiness
    # test let a shard-shaped invocation through: `--self-test --shard ''` printed a clean suite
    # result at rc 0. Third instance of one defect (round 1 reported it, round 5 fixed `main`'s
    # `if a.shard:`, this is `shard_mode_refusal`'s).
    # ⛔ AGREEMENT WITH argparse's OWN RULE, asked of argparse — round 7 codex Low. Asserting my
    # belief about the normalisation would be a second implementation of it; this builds a throwaway
    # parser with a HYPHENATED flag and checks the round trip, so the case fails if argparse ever
    # normalises differently than `shard_dest` does.
    def _roundtrip(_opt: str):
        """-> the value argparse stored, looked up the way `main` looks it up.

        ⛔ argparse CHOOSES the dest; `shard_dest` must agree with that choice. An earlier draft
        passed `dest=shard_dest(_opt)`, so both sides read one function and the mutation survived.
        ⚠ A miss is returned as a VALUE rather than raised, or the suite dies before printing
        `[FAIL] <case>` — the same trap the length case fell into one fold ago.
        """
        _p = argparse.ArgumentParser(add_help=False)
        _p.add_argument(f"--{_opt}", metavar="I/N")
        try:
            return getattr(_p.parse_args([f"--{_opt}", "2/5"]), shard_dest(_opt))
        except Exception as exc:                  # noqa: BLE001 — round 8 L2
            # ⚠ NOT just `AttributeError`. A `TypeError` from a malformed name would kill the suite
            # before it printed `[FAIL] <case>`, making the mutation unattributable — the same trap
            # the length case fell into two folds ago. Any failure becomes a VALUE here.
            return f"MISSED — shard_dest disagrees with argparse ({type(exc).__name__})"

    # ⛔ BOTH OF argparse's STEPS NEED AN INPUT THAT EXERCISES THEM — r8 codex High. `shard-x`
    # round-trips identically with or without `lstrip("-")`, so the mutation deleting the strip
    # SURVIVED (CI shard 2) while this case stayed green: the case did not test the behaviour its
    # own entry names. A LEADING-hyphen key is the discriminating input — argparse sees the option
    # `---shard-x` and names it `shard_x`, while replace-only yields `_shard_x`.
    case("a hyphenated flag round-trips through `shard_dest` exactly as argparse names it",
         (_roundtrip("shard-x"), _roundtrip("-shard-x")), ("2/5", "2/5"))
    case("...and every shipped key survives the same normalisation",
         tuple(shard_dest(_k) for _k in SHARD_FLAGS), tuple(SHARD_FLAGS))

    # ── r8 CODEX LOW — a colliding key is a DECLARATION error and gets ONE sentence, not four
    # different shapes. Measured before the guard: `mutate`/`compare` raised argparse's own
    # "conflicting option string", `self_test` produced a nonsense refusal about `--self_test True`,
    # and `plan` silently reddened an unrelated case.
    def _collide(_key: str) -> str:
        _saved = globals()["SHARD_FLAGS"]
        globals()["SHARD_FLAGS"] = {"shard": _saved["shard"], _key: (False, "colliding")}
        try:
            # ⛔ `main([])`, NEVER `main(["--self-test"])` — the parser is built either way, but
            # `--self-test` RE-ENTERS the suite currently running this case. It terminated only
            # because the guard raises during construction; severing the guard recursed until the
            # 150s timeout, measured. That is the same shape as the `--mutate .` defect fixed forty
            # lines above — a case whose COST depends on the mutation it tests — and this one was
            # written after that lesson. An empty argv builds the parser and refuses for want of a
            # mode: cheap under every mutation.
            main([])
            return "NO ERROR"
        except ValueError as exc:
            return "refused" if f"{_key!r} collides" in str(exc) else f"wrong text: {exc}"
        except Exception as exc:                  # noqa: BLE001 — the TYPE is the evidence
            return f"{type(exc).__name__}"
        finally:
            globals()["SHARD_FLAGS"] = _saved

    case("a SHARD_FLAGS key colliding with an existing option is refused by name — r8 codex Low",
         tuple(_collide(_k) for _k in ("mutate", "compare", "self_test", "plan")),
         ("refused",) * 4)

    # ── ROUND 8 M1 — THE CLAIM, MADE CHECKABLE. "A third flag is one dict entry" was false: the
    # dict covered argparse registration and the mode refusal, while exclusivity, parsing and
    # zero-basedness were hand-written against `a.shard`/`a.shard0`. FIVE readers, not two. The
    # reviewer's exhibit — add a key, watch the flag be accepted and never parsed — is the case.
    # ⛔ AN EMPTY ROOT, NOT `.` — the rule stated forty lines below, which these two cases were
    # written directly above and then broke. With `--mutate .` a mutation that severs either
    # refusal makes these calls start THE REAL SWEEP inside one mutation's suite run:
    # `SUITE_TIMEOUT`, recorded as NOT CHECKED rather than as a catch, and the whole shard voided.
    # MEASURED — CI shards 1, 2 and 4 went red on `56eafeef` for exactly this. Over an empty root a
    # severed refusal instead hits the count drift (rc 1, no suite), a DIFFERENT answer a case can
    # read.
    _third = dict(SHARD_FLAGS, shard2=(False, "a third key, added in-process"))
    _saved_flags = globals()["SHARD_FLAGS"]
    globals()["SHARD_FLAGS"] = _third
    try:
        with tempfile.TemporaryDirectory() as _emptyroot:
            _se3 = io.StringIO()
            with contextlib.redirect_stderr(_se3):
                _rc_unparsed = main(["--mutate", _emptyroot, "--shard2", "garbage"])
            _unparsed_out = _se3.getvalue()
            _se4 = io.StringIO()
            with contextlib.redirect_stderr(_se4):
                _rc_both = main(["--mutate", _emptyroot, "--shard2", "1/8", "--shard", "1/8"])
            _both_out = _se4.getvalue()
    finally:
        globals()["SHARD_FLAGS"] = _saved_flags
    case("a flag added to SHARD_FLAGS is PARSED, not merely accepted — round 8 M1",
         (_rc_unparsed, "not of the form I/N" in _unparsed_out), (2, True))
    case("...and is mutually exclusive with the others, without being named anywhere — round 8 M1",
         (_rc_both, "same control" in _both_out), (2, True))

    case("an EMPTY shard value is still a shard-shaped invocation, for every flag — round 7 H1",
         tuple(shard_mode_refusal("", None, flag=f"--{_f}") is not None for _f in SHARD_FLAGS),
         tuple(True for _f in SHARD_FLAGS))
    # ⚠ The digit run's LENGTH, not its alphabet — round 7 L1. `int()` refuses beyond 4300 digits,
    # so an unbounded `[0-9]*` matched a string the conversion then raised on.
    # ⚠ BOTH SIDES. The bound appears twice in the pattern, so a mutation may remove only one —
    # asserting a long INDEX alone would leave a long TOTAL unguarded, which is the "two distinct
    # inputs" rule applied to one expression.
    # ⛔ AND IT MUST OBSERVE A RAISE RATHER THAN SUFFER ONE. The first draft asserted the RETURN
    # VALUE, so removing the bound made `parse_shard` raise and the suite died BEFORE printing any
    # `[FAIL] <case>` line: shard 6 reported `151 killed, 150 attributed` — killed by something, the
    # clause proven by nothing. That is the hazard this function's own comment names twenty lines
    # above, and the first draft walked into it. Converting the raise into a comparable value makes
    # the case assert the docstring's actual promise — A SENTENCE AND A CANNOT RUN, NEVER A
    # TRACEBACK — instead of only the happy path's return value.
    def _parsed_or_raised(spec: str):
        try:
            return parse_shard(spec)[0]
        except Exception as exc:                      # noqa: BLE001 — the TYPE is the evidence
            return f"RAISED {type(exc).__name__}"

    case("a digit run longer than the bound is REFUSED on either side, never raised — r7 L1",
         (_parsed_or_raised("1" * 4301 + "/8"), _parsed_or_raised("1/" + "8" * 4301),
          _parsed_or_raised("1/9999"), _parsed_or_raised("1/10000")),
         (None, None, (1, 9999), None))
    # ⛔ AN EMPTY ROOT, NOT `.`, AND THAT IS NOT TIDINESS. With `--mutate .` this case would run
    # THE REAL SWEEP the moment the refusal below it is severed — eight minutes inside a
    # self-test, and inside the mutation harness a `SUITE_TIMEOUT` CANNOT RUN, which is recorded
    # as "not checked" rather than as a catch. Over an empty root the severed path instead hits
    # the count drift (rc 1, no suite), which is a DIFFERENT answer a case can read.
    with tempfile.TemporaryDirectory() as _td:
        _se2 = io.StringIO()
        with contextlib.redirect_stderr(_se2):
            _rc_bad = main(["--mutate", _td, "--shard", "two/five"])
        case("...and a malformed --shard refuses BEFORE any suite runs",
             (_rc_bad, "not of the form I/N" in _se2.getvalue()), (2, True))
    # ⛔ AND THE EMPTY SHARD EXITS 2, NOT 1. The count lives in the manifest, so this is the
    # one refusal `main` cannot make from its arguments alone — and it must be a CANNOT RUN:
    # rc 1 from this path would read as "a mutation survived" in a CI log, which is a verdict
    # about code rather than the truth, which is that nothing was measured.
    # ⚠ N=9 OVER A 2-ENTRY MANIFEST, so no suite can run either way: if this clause were
    # severed the run would hit the count drift against the REAL `EXPECTED_MUTATIONS` and
    # return 1 — a different number, which is what makes the case fail rather than hang.
    with tempfile.TemporaryDirectory() as _td:
        _re = pathlib.Path(_td); _mini(_re, second=True)
        _se3 = io.StringIO()
        with contextlib.redirect_stderr(_se3):
            _rc_empty = main(["--mutate", str(_re), "--shard", "9/9"])
        case("⛔ a shard that is empty over the real manifest exits 2 (CANNOT RUN), not 1",
             (_rc_empty, "is EMPTY" in _se3.getvalue()), (2, True))

    # ── THE CONSUMER'S PARSE, pinned where it lives (r2 M2 + L1) ─────────────────────────
    case("the consumer reads a case name off a [FAIL] line",
         parse_fail_names("  [FAIL] a case: got 1 want 2"), ["a case"])
    case("...and ignores a marker that is not at the start of the line",
         parse_fail_names("> note: mid-line [FAIL] marker"), [])
    # ⚠ THE CLAUSE THE PRODUCER-SIDE CASE DID NOT MODEL. A name containing ": got " is truncated,
    # so an `expect` naming it in full could never match and its entry would be unattributable.
    case("⚠ a case name containing ': got ' is TRUNCATED by the consumer",
         parse_fail_names("  [FAIL] the width: got the wrong value"), ["the width"])
